/**
 * @param {string} s
 * @param {string} t
 * @return {character}
 */
const findTheDifference = function (s, t) {
  const sCountMap = new Map();
  const tCountMap = new Map();

  const assignValue = (map, char) => {
    if (map.has(char)) {
      map.set(char, map.get(char) + 1);
    } else {
      map.set(char, 1);
    }
  };

  for (let i = 0; i < t.length; i++) {
    assignValue(sCountMap, s[i]);
    assignValue(tCountMap, t[i]);
  }

  for (const [key, value] of tCountMap) {
    if (!sCountMap.has(key)) return key;

    if (sCountMap.get(key) !== value) return key;
  }
};

console.log(
  findTheDifference(
    "",
    "",
  ),
);
